#!/usr/bin/env python3
"""Regenera os HTMLs do system design quando o JSON for mais recente que eles.

Compara a data de modificação de system-design/qore-system-design.json com a dos dois
HTMLs gerados (proposta e aprovado). Se o JSON for mais novo, ou se algum HTML não
existir, roda o gerar.py (sem capturas).

Uso, a partir da raiz do repositório:
    python3 .claude/skills/system-design/scripts/sincronizar.py
        # regenera se preciso e diz o que fez
    python3 .claude/skills/system-design/scripts/sincronizar.py --hook PostToolUse
        # modo hook: lê o evento na entrada padrão; só imprime (JSON com
        # additionalContext) quando regenerou ou quando a geração falhou.

Só usa a biblioteca padrão do Python.
"""
import argparse
import json
import subprocess
import sys
from pathlib import Path

SKILL = Path(__file__).resolve().parents[1]
RAIZ = SKILL.parents[2]
DADOS = RAIZ / "system-design" / "qore-system-design.json"
SAIDAS = [RAIZ / "system-design" / "qore-system-design-proposta.html",
          RAIZ / "system-design" / "qore-system-design-aprovado.html"]
GERAR = SKILL / "scripts" / "gerar.py"


def precisa_gerar():
    if not DADOS.exists():
        return False
    json_mtime = DADOS.stat().st_mtime
    return any(not s.exists() or s.stat().st_mtime < json_mtime for s in SAIDAS)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--hook", metavar="EVENTO", help="modo hook (PostToolUse ou UserPromptSubmit)")
    a = ap.parse_args()
    if a.hook:
        sys.stdin.read()  # o evento não é usado: a comparação olha as datas dos arquivos

    if not precisa_gerar():
        if not a.hook:
            print("os HTMLs já estão em dia com o JSON")
        return

    r = subprocess.run([sys.executable, str(GERAR)], cwd=RAIZ, capture_output=True, text=True, timeout=120)
    saida = (r.stdout + r.stderr).strip()
    erros = [l for l in saida.splitlines() if l.startswith("ERRO")]
    if r.returncode == 0:
        msg = ("O JSON do system design mudou, e os HTMLs (proposta e aprovado) foram regenerados "
               "automaticamente. Confira as capturas com gerar.py --capturas se a mudança for visual.")
    else:
        msg = ("O JSON do system design mudou, mas a regeneração dos HTMLs falhou: "
               + "; ".join(erros or [saida[-500:]]) + ". Corrija o JSON.")

    if a.hook:
        print(json.dumps({"hookSpecificOutput": {"hookEventName": a.hook, "additionalContext": msg}},
                         ensure_ascii=False))
    else:
        print(msg)
        sys.exit(r.returncode)


if __name__ == "__main__":
    main()
=====APROVACOES=====
#!/usr/bin/env python3
"""Detecta documentos de engenharia que o system design ou a rastreabilidade ainda não refletiram.

Acompanha os PRDs, RFCs, ADRs e FDDs de docs/ (pelo frontmatter `tipo` e `status`).
O JSON do diagrama guarda em meta.documentos_status o status de cada um
({"rfc-0001-integracao-com-o-pncp": "aprovado", ...}), como a skill system-design
o considerou da última vez. Este script avisa quando:
    - um documento é novo (não está em meta.documentos_status);
    - o status de um documento mudou (ex.: rascunho -> aprovado, proposto -> aceito);
    - um documento registrado deixou de existir;
    - um documento acompanhado não é citado em docs/engenharia/rastreabilidade.md.

Uso, a partir da raiz do repositório:
    python3 .claude/skills/system-design/scripts/aprovacoes.py
        # lista as pendências; código de saída 1 se houver alguma
    python3 .claude/skills/system-design/scripts/aprovacoes.py --hook PostToolUse
        # modo hook: lê o evento na entrada padrão e, se houver pendência, devolve
        # JSON com additionalContext pedindo ao Claude que rode a skill system-design.
        # Sem pendência, não imprime nada.

Só usa a biblioteca padrão do Python.
"""
import argparse
import json
import re
import sys
from pathlib import Path

SKILL = Path(__file__).resolve().parents[1]
RAIZ = SKILL.parents[2]
DADOS = RAIZ / "system-design" / "qore-system-design.json"
RASTREABILIDADE = RAIZ / "docs" / "engenharia" / "rastreabilidade.md"
TIPOS = {"prd", "rfc", "adr", "fdd"}


def frontmatter(texto):
    if not texto.startswith("---"):
        return {}
    fim = texto.find("\n---", 3)
    if fim < 0:
        return {}
    campos = {}
    for linha in texto[3:fim].splitlines():
        m = re.match(r"^(tipo|status):\s*[\"']?([\w-]+)", linha)
        if m:
            campos[m.group(1)] = m.group(2).lower()
    return campos


def documentos():
    """Status atual de cada PRD, RFC, ADR e FDD: {nome da nota: status}."""
    docs = {}
    for p in (RAIZ / "docs").rglob("*.md"):
        try:
            fm = frontmatter(p.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError):
            continue
        if fm.get("tipo") in TIPOS:
            docs[p.stem] = fm.get("status", "")
    return docs


def registrados():
    """Status de cada documento como o diagrama o considerou: meta.documentos_status."""
    try:
        meta = json.loads(DADOS.read_text(encoding="utf-8")).get("meta", {})
    except (OSError, json.JSONDecodeError):
        return {}
    return dict(meta.get("documentos_status", {}))


def pendencias():
    atuais, vistos = documentos(), registrados()
