                  + "Documentos que não aparecem em docs/engenharia/rastreabilidade.md: "
                  + ", ".join(f"[[{n}]]" for n in sem_rastro)
                  + ". Acrescente-os ao ciclo de vida e registre a origem das decisões deles.")
    return texto


def main():
