};

/* legenda no canto superior esquerdo */
(function legend() {
  const g = document.getElementById("legend");
  const items = [
    ["app", C.cyan, "#10303b", ""], ["banco", "#9cbcff", "#3f73dc", ""],
    ["processo", C.violet, "#241d3a", ""], ["futuro / a confirmar", "#8b93a1", "#1f2229", "6 5"],
  ];
  items.forEach(([txt, stroke, fill, da], i) => {
    const y = 130 + i * 34;
    el("rect", { x: 50, y: y - 11, width: 30, height: 22, rx: 5, fill, stroke, "stroke-width": 2,
      ...(da ? { "stroke-dasharray": da } : {}) }, g);
    label(g, 92, y + 1, txt, 18, C.muted, { "text-anchor": "start" });
  });
})();

const nodeEls = {}, edgeEls = {};
const gEdges = document.getElementById("edges");
const gNodes = document.getElementById("nodes");
const gPackets = document.getElementById("packets");
const pathD = pts => "M" + pts.map(p => p.join(",")).join(" L");

for (const [id, e] of Object.entries(EDGES)) {
  if (e.hidden) continue;
  edgeEls[id] = el("path", { class: "edge", d: pathD(e.pts), fill: "none", stroke: C.line,
    "stroke-width": 2, "stroke-linejoin": "round", ...(e.future ? { "stroke-dasharray": "6 6" } : {}) }, gEdges);
}
for (const [id, n] of Object.entries(NODES)) {
  const g = el("g", { class: "node" }, gNodes);
  DRAW[n.type](g, n);
  nodeEls[id] = g;
}

/* uma conexão acende quando os nós das duas pontas estão na cena */
function edgeVisible(id, on) {
  if (EDGES[id].decorative) return on.size === ALL.length;
  const pts = EDGES[id].pts, near = (n, p) => Math.abs(n.x - p[0]) <= 80 && Math.abs(n.y - p[1]) <= 56;
  const ends = [pts[0], pts[pts.length - 1]];
  return ends.every(p => Object.entries(NODES).some(([k, n]) => on.has(k) && near(n, p)));
}

/* ---------- Cena atual ---------- */
const title = document.getElementById("title");
const subtitle = document.getElementById("subtitle");
const caption = document.getElementById("caption");
const capText = document.getElementById("capText");
const capBox = document.getElementById("capBox");
const dots = document.getElementById("dots");
let cur = 0, playing = true, timer = null;
const DURATION = 4200;

SCENES.forEach((_, i) => {
  const d = document.createElement("span");
  d.onclick = ev => { ev.stopPropagation(); go(i); };
  dots.appendChild(d);
});

function setRich(t, [a, b], accent) {
  t.textContent = "";
  el("tspan", { fill: C.text }, t).textContent = a;
  el("tspan", { fill: accent }, t).textContent = b;
}

function packets(ids) {
  gPackets.textContent = "";
  ids.forEach((id, k) => {
    const e = EDGES[id];
    if (e.decorative) return;
    const d = pathD(e.pts);
    const len = e.pts.slice(1).reduce((s, p, i) =>
      s + Math.hypot(p[0] - e.pts[i][0], p[1] - e.pts[i][1]), 0);
    const dur = Math.max(0.9, len / 170);
    for (let j = 0; j < 2; j++) {
      const begin = (j * dur / 2 + k * 0.12) + "s";
      const c = el("circle", { r: 5, fill: e.future ? C.muted : C.blue, opacity: 0 }, gPackets);
      el("animateMotion", { dur: dur + "s", begin, repeatCount: "indefinite", path: d }, c);
      el("animate", { attributeName: "opacity", values: "0;1;1;0", keyTimes: "0;0.1;0.85;1",
        dur: dur + "s", begin, repeatCount: "indefinite" }, c);
    }
  });
  document.getElementById("stage").setCurrentTime?.(0);
}

function go(i) {
  cur = (i + SCENES.length) % SCENES.length;
  const s = SCENES[cur], on = new Set(s.nodes);
  for (const t of [title, subtitle, caption]) t.style.opacity = 0;
  setTimeout(() => {
    setRich(title, s.title, C.blue);
    setRich(subtitle, s.sub, C.cyan);
    capText.textContent = s.cap;
    const w = Math.max(260, capText.getComputedTextLength() + 64);
    capBox.setAttribute("x", 800 - w / 2); capBox.setAttribute("width", w);
    for (const t of [title, subtitle, caption]) t.style.opacity = 1;
  }, 180);
  for (const [id, g] of Object.entries(nodeEls)) g.classList.toggle("dim", !on.has(id));
  for (const [id, p] of Object.entries(edgeEls)) p.classList.toggle("dim", !edgeVisible(id, on));
  packets(s.packets);
  [...dots.children].forEach((d, k) => d.classList.toggle("on", k === cur));
  schedule();
}

function schedule() {
  clearTimeout(timer);
  if (playing) timer = setTimeout(() => go(cur + 1), DURATION);
}
function toggle() {
  playing = !playing;
  document.getElementById("play").textContent = playing ? "❚❚" : "▶︎";
  schedule();
}

document.getElementById("stage").onclick = () => go(cur + 1);
document.getElementById("next").onclick = () => go(cur + 1);
document.getElementById("prev").onclick = () => go(cur - 1);
document.getElementById("play").onclick = toggle;
document.addEventListener("keydown", ev => {
  if (ev.key === "ArrowRight") go(cur + 1);
  else if (ev.key === "ArrowLeft") go(cur - 1);
  else if (ev.key === " ") { ev.preventDefault(); toggle(); }
});

const params = new URLSearchParams(location.search);
if (params.has("pausado")) toggle();
if (params.has("captura")) document.body.classList.add("captura");
(document.fonts?.ready || Promise.resolve()).then(() => go(Number(params.get("cena")) || 0));
</script>
</body>
</html>

