"""Reconhecimento de valores monetários no texto (FDD-0009, seção 6).

Reconhece valores com R$ e números com separador decimal. Inteiros sem R$ (prazos, idades, anos) são ignorados.
Formato brasileiro: ponto é milhar e vírgula é decimal. Número com ponto decimal e sem vírgula usa o ponto como decimal.
"""

from __future__ import annotations

import re
from decimal import Decimal, ROUND_HALF_UP

# R$ 119,90 | R$ 4.500,00 | R$ 4500 | R$ 119.90
_VALOR_RS = re.compile(r"R\$\s?(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d+(?:,\d{1,2})?|\d+\.\d{1,2})")
# 119,90 | 4.500,00 | 119.90, sem R$
_VALOR_DECIMAL = re.compile(
    r"(?<![\w.,])(\d{1,3}(?:\.\d{3})+,\d{1,2}|\d+,\d{1,2}|\d+\.\d{1,2})(?![\w,]|\.\d)"
)


def _converter(bruto: str, com_rs: bool) -> Decimal:
    if "," in bruto:
        numero = bruto.replace(".", "").replace(",", ".")
    elif com_rs and re.fullmatch(r"\d{1,3}(\.\d{3})+", bruto):
        numero = bruto.replace(".", "")  # R$ 4.500 é milhar, não decimal
    else:
        numero = bruto
    return Decimal(numero).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def extrair_valores(texto: str) -> list[tuple[Decimal, int]]:
    """Devolve (valor, posição) de cada valor reconhecido, em ordem de posição no texto."""
    encontrados: list[tuple[Decimal, int]] = []
    ocupados: list[tuple[int, int]] = []
    for casamento in _VALOR_RS.finditer(texto):
        encontrados.append((_converter(casamento.group(1), com_rs=True), casamento.start()))
        ocupados.append(casamento.span())
    for casamento in _VALOR_DECIMAL.finditer(texto):
        inicio, fim = casamento.span()
        if any(inicio < o_fim and fim > o_inicio for o_inicio, o_fim in ocupados):
            continue
        encontrados.append((_converter(casamento.group(1), com_rs=False), inicio))
    return sorted(encontrados, key=lambda par: par[1])

"""Verificação R1 em código: todo valor do rascunho existe na cotação, no plano correto (FDD-0009, seção 7)."""

from __future__ import annotations

import re
from dataclasses import dataclass
from decimal import Decimal

from autoseguro.juiz.extracao import extrair_valores


@dataclass(frozen=True)
class ResultadoR1:
    aprovado: bool
    motivo: str = ""


def _valores_do_plano(plano: dict) -> set[Decimal]:
    valores = {Decimal(str(plano["premio_mensal"])), Decimal(str(plano["franquia"]))}
    if plano.get("primeiro_pagamento_pro_rata") is not None:
        valores.add(Decimal(str(plano["primeiro_pagamento_pro_rata"])))
    return {v.quantize(Decimal("0.01")) for v in valores}


def _frases(texto: str) -> list[str]:
    return [f for f in re.split(r"(?<=[.;!?])\s+|\n+", texto) if f.strip()]


def verificar(rascunho: str, planos: list[dict] | None) -> ResultadoR1:
    """Aprova se todo valor do rascunho está permitido. Sem cotação, nenhum valor é permitido (OBJ-3)."""
    if not extrair_valores(rascunho):
        return ResultadoR1(True)
    if not planos:
        return ResultadoR1(False, "valor citado sem cotação")

    por_plano = {p["plano_nome"].lower(): _valores_do_plano(p) for p in planos}
    geral: set[Decimal] = set().union(*por_plano.values())

    for frase in _frases(rascunho):
        valores = extrair_valores(frase)
        if not valores:
            continue
        citados = [nome for nome in por_plano if nome in frase.lower()]
        permitidos = por_plano[citados[0]] if len(citados) == 1 else geral
        for valor, _ in valores:
            if valor.quantize(Decimal("0.01")) not in permitidos:
                return ResultadoR1(False, "valor fora da cotação oficial")
    return ResultadoR1(True)

"""Orquestração do juiz: R1 em código, depois R2 a R4 pelo modelo (FDD-0009 seções 7 a 10).

Nenhuma falha do juiz libera o rascunho. Falha fechada, conforme a RFC-0009.
"""

from __future__ import annotations

import json
import time
from typing import Callable

from pydantic import ValidationError

from autoseguro.juiz import prompts, r1
from autoseguro.juiz.modelos import DecisaoJuiz, VeredictoJuiz
from autoseguro.logs import obter_logger
from autoseguro.mascaramento import detectar
from autoseguro.juiz.extracao import extrair_valores

_log = obter_logger("autoseguro.juiz")

TENTATIVAS = 3
ESPERAS = (0.5, 1.0)
MOTIVO_FALHA = "falha do juiz"
MOTIVO_OMITIDO = "motivo omitido"


class Juiz:
    def __init__(self, modelo, sleep: Callable[[float], None] = time.sleep):
        """`modelo` implementa `estruturar(sistema, conteudo, schema)`, que devolve uma instância de schema."""
        self._modelo = modelo
        self._sleep = sleep

    def avaliar(
        self,
        rascunho: str,
        planos: list[dict] | None,
        status: str,
        motivo_cotacao: str | None,
    ) -> DecisaoJuiz:
        r1_resultado = r1.verificar(rascunho, planos)
        if not r1_resultado.aprovado:
            _log.info("juiz reprovou em R1", extra={"evento": "juiz", "detalhe": {"regra": "R1"}})
            return DecisaoJuiz(aprovado=False, regra="R1", motivo=r1_resultado.motivo, tentativas=0)

        conteudo = json.dumps(
            {
                "rascunho": rascunho,
                "status": status,
                "motivo_cotacao": motivo_cotacao,
                "planos": planos or [],
            },
            ensure_ascii=False,
            default=str,
        )
        ultimo_erro: Exception | None = None
        for numero in range(1, TENTATIVAS + 1):
            try:
                veredicto = self._modelo.estruturar(prompts.INSTRUCOES, conteudo, VeredictoJuiz)
                if not isinstance(veredicto, VeredictoJuiz):
                    raise TypeError("saída fora do formato VeredictoJuiz")
                return self._decidir(veredicto, numero)
            except (ValidationError, TypeError, ValueError, RuntimeError) as erro:
                ultimo_erro = erro
                _log.warning("falha do juiz, tentativa", extra={"evento": "juiz_falha",
                                                                "detalhe": {"tentativa": numero}})
                if numero < TENTATIVAS:
                    self._sleep(ESPERAS[numero - 1])
        _log.error("juiz falhou após três tentativas", extra={"evento": "juiz_falha_total",
                                                              "detalhe": {"tipo": type(ultimo_erro).__name__}})
        return DecisaoJuiz(aprovado=False, regra=None, motivo=MOTIVO_FALHA, tentativas=TENTATIVAS)

    @staticmethod
    def _decidir(veredicto: VeredictoJuiz, tentativas: int) -> DecisaoJuiz:
        motivo = _sanitizar_motivo(veredicto.motivo)
        if veredicto.aprovado:
            return DecisaoJuiz(aprovado=True, regra=None, motivo="", tentativas=tentativas)
        return DecisaoJuiz(aprovado=False, regra=veredicto.regra, motivo=motivo, tentativas=tentativas)


def _sanitizar_motivo(motivo: str) -> str:
    """O motivo vai para os traces. Se tiver valor monetário ou dado pessoal, é omitido (FDD-0009, seção 9)."""
    if extrair_valores(motivo) or detectar(motivo) or "R$" in motivo:
        return MOTIVO_OMITIDO
    return motivo

